  "intro": [
   "เช้าวันหนึ่ง ครูสมศักดิ์ หัวหน้างานปกครอง ใช้กรรไกรตัดผมนักเรียนชายที่ผมยาวเกินกติกาเดิมของโรงเรียนต่อหน้าแถว คลิปถูกส่งต่อในโซเชียลมีเดียภายในชั่วโมง น้องฟ้า ประธานสภานักเรียน ขอพบผู้อำนวยการพร้อมรายชื่อนักเรียนที่ขอให้ทบทวนกติกาทรงผม"
  ],
  "realCase": "เมื่อ 21 พฤศจิกายน 2567 ศธ. ย้ำว่าการลงโทษนักเรียนมีเพียง 4 สถาน ได้แก่ ว่ากล่าวตักเตือน ทำทัณฑ์บน ตัดคะแนนความประพฤติ และทำกิจกรรมเพื่อปรับเปลี่ยนพฤติกรรม (<a href=\"https://www.dailynews.co.th/news/4464215/\" target=\"_blank\" rel=\"noopener\">เดลินิวส์</a>) ระเบียบ ศธ. ว่าด้วยทรงผม 2563 ถูกยกเลิกเมื่อปี 2566 โดยให้กติกาของโรงเรียนต้องมีส่วนร่วมของนักเรียน ได้รับความเห็นชอบจากคณะกรรมการสถานศึกษา และประกาศให้นักเรียนทราบ และศาลปกครองสูงสุดเพิกถอนกฎกระทรวงเรื่องทรงผมฉบับปี 2518 เมื่อ 5 มีนาคม 2568 (<a href=\"https://www.thaipbs.or.th/news/content/349913\" target=\"_blank\" rel=\"noopener\">Thai PBS</a>)",
