  "intro": [
   "ต้นภาคเรียนที่ 1 เงินอุดหนุนเรียนฟรีเข้าบัญชีโรงเรียนพร้อมกันหลายก้อน ตัวแทนสำนักพิมพ์มาเสนอส่วนลดพิเศษถ้าโรงเรียนสั่งหนังสือทั้งชุดภายในสัปดาห์นี้ ครูประจำชั้นถามเรื่องการจ่ายค่าอุปกรณ์และค่าเครื่องแบบ ส่วนหัวหน้ากลุ่มสาระวิทยาศาสตร์ขอซื้อสารเคมีและอุปกรณ์ทดลองรวมราว 180,000 บาท โดยเสนอให้แยกซื้อทีละห้องปฏิบัติการ"
  ],
  "realCase": "เอกสารอบรมของ สพม. แห่งหนึ่ง (พฤษภาคม 2567) สรุปกฎย่อยของเงินอุดหนุน 5 รายการ ค่าหนังสือให้ครูผู้สอนเป็นผู้คัดเลือก และต้องผ่านความเห็นชอบของภาคี 4 ฝ่าย ค่าอุปกรณ์และค่าเครื่องแบบต้องตั้งผู้จ่ายเงินอย่างน้อย 2 คนโดยมีครูประจำชั้นร่วมด้วย ส่วนเงินปัจจัยพื้นฐานนักเรียนยากจนให้เฉพาะ ม.ต้น ปีละ 3,000 บาท และถ้าจ่ายเป็นเงินสดต้องมีกรรมการจ่ายเงินอย่างน้อย 3 คน (<a href=\"https://www.sea12.go.th/asset/images/stories/form/2.5.67/2.1.pdf\" target=\"_blank\" rel=\"noopener\">สพม.อบรม 2567</a>) สำนักข่าวอิศรามีพาดหัวคดีผู้บริหารโรงเรียนแห่งหนึ่ง \"ทุจริตแบ่งซื้อหนังสือเรียน\" แต่ยังเปิดอ่านรายละเอียดไม่ได้ จึงใช้เป็นภาพประกอบได้เท่านั้น (<a href=\"https://www.isranews.org/article/isranews-news/122729-inves09-545-126.html\" target=\"_blank\" rel=\"noopener\">อิศรา พาดหัว</a>)",
