  "id": 8,
  "title": "โครงการใหม่ในสัปดาห์ส่ง SAR",
  "area": "academic",
  "areaTh": "วิชาการ",
  "difficulty": 2,
  "difficultyTh": "กลาง",
  "intro": [
   "สัปดาห์เดียวกับที่โรงเรียนต้องส่งรายงานการประเมินตนเอง (SAR) เขตพื้นที่ส่งหนังสือให้ทุกโรงเรียนเข้าร่วมโครงการใหม่ที่มีแบบรายงาน 6 หน้า ครูวิไลบอกตรง ๆ ว่าครูทำ PA เอกสารนิเทศ และโครงการรวมกันจนแทบไม่มีเวลาเตรียมสอน ศน.ปกรณ์แนะนำให้ใช้ SAR เป็นเครื่องมือพัฒนา ไม่ใช่เพียงเอกสารส่ง"
  ],
  "realCase": "นโยบาย \"เรียนดี มีความสุข\" (เมษายน 2567) ตั้งเป้าลดภาระครู ใช้ระบบประเมิน PA แบบดิจิทัล (DPA) และวางแผนลดโครงการและตัวชี้วัดที่ซ้ำซ้อน (<a href=\"https://www.dailynews.co.th/news/3319870/\" target=\"_blank\" rel=\"noopener\">เดลินิวส์</a>) กฎกระทรวงการประกันคุณภาพการศึกษา พ.ศ. 2561 ให้สถานศึกษาส่ง SAR ให้หน่วยงานต้นสังกัดทุกปี (<a href=\"https://so02.tci-thaijo.org/index.php/jgsnsbc-journal/article/download/256278/172204/955796\" target=\"_blank\" rel=\"noopener\">วารสาร TCI</a>) ส่วน สมศ. ลดการลงพื้นที่เหลือ 1 วันและจะใช้รูปแบบใหม่เต็มรูปแบบในปีงบประมาณ 2570 (<a href=\"https://www.thaipost.net/public-relations-news/838740/\" target=\"_blank\" rel=\"noopener\">ไทยโพสต์</a>) ผู้อำนวยการสถานศึกษาก็ต้องจัดทำ PA ของตนเองและต้องสอนอย่างน้อย 5 ชั่วโมงต่อสัปดาห์ตามสรุปหลักเกณฑ์ ว 10/2564 ของสำนักงาน ก.ค.ศ. (<a href=\"https://otepc.go.th/th/content_page/download/345/4351/17.html\" target=\"_blank\" rel=\"noopener\">OTEPC</a>)",
  "ambiguity": "",
  "commandNote": "ครูอรุณ (R4) \"มอบหมาย\" ได้ ครูวิไล (R3) ต้องการ \"สนับสนุน\"",
