  "difficulty": 2,
  "difficultyTh": "กลาง",
  "intro": [
   "กลุ่มสาระวิทยาศาสตร์เสนอพานักเรียน ม.4 จำนวน 120 คนไปค่ายวิทยาศาสตร์ทางทะเล 2 วัน 1 คืน ใช้รถบัสเช่า 3 คัน ผู้ปกครองบางคนยังจำข่าวไฟไหม้รถทัศนศึกษาในปี 2567 ได้และกังวลมาก ครูพลศึกษาอาสาเป็นผู้ประสานงาน ส่วนรองฯ ประเสริฐดูแลเรื่องรถ"
  ],
  "realCase": "ระเบียบ ศธ. ว่าด้วยการพานักเรียนและนักศึกษาไปนอกสถานศึกษา พ.ศ. 2562 (แก้ไขเพิ่มเติม พ.ศ. 2563) กำหนดให้นักเรียนไปด้วยความสมัครใจและได้รับอนุญาตจากผู้ปกครอง โรงเรียนรัฐต้องยื่นขออนุญาตล่วงหน้าอย่างน้อย 15 วัน การไปค้างคืนต้องได้รับอนุญาตจากผู้อำนวยการเขตพื้นที่ มีผู้ควบคุมและผู้ช่วยผู้ควบคุมตามอัตราส่วนต่อนักเรียน 30 คน ยานพาหนะต้องมั่นคงแข็งแรง มีประกันอุบัติเหตุ มีแผนสำรองฉุกเฉิน และต้องรายงานผลต่อผู้อนุญาตหลังกลับ (<a href=\"https://www.naewna.com/likesara/832779\" target=\"_blank\" rel=\"noopener\">แนวหน้า</a>) หลังเหตุรถทัศนศึกษาเกิดไฟไหม้บนถนนสายหลักในจังหวัดปริมณฑลเมื่อ 1 ตุลาคม 2567 ซึ่งมีนักเรียนและครูเสียชีวิตจำนวนมาก ศธ. สั่งงดทัศนศึกษาโดยไม่มีกำหนด เว้นกรณีจำเป็น และกำหนดเงื่อนไขเพิ่ม เช่น ผู้อำนวยการต้องไปควบคุมเอง และรถมีอายุไม่เกิน 5 ปี (<a href=\"https://thestandard.co/bus-fire-safety-review-field-trips-debate/\" target=\"_blank\" rel=\"noopener\">THE STANDARD</a>; <a href=\"https://www.naewna.com/local/832852\" target=\"_blank\" rel=\"noopener\">แนวหน้า</a>) แต่ยังยืนยันไม่ได้ว่าข้อสั่งการนี้ยังมีผลหรือถูกยกเลิกเมื่อใด ตัวเลือกที่อาศัยข้อสั่งการปี 2567 จึงไม่ตัดสินในชั้นที่ 1",
