  "area": "budget",
  "areaTh": "งบประมาณ",
  "difficulty": 3,
  "difficultyTh": "ยาก",
  "intro": [
   "โรงเรียนได้รับจัดสรรงบลงทุนปรับปรุงสนามกีฬาในร่ม วงเงิน 1.8 ล้านบาท ที่ปรึกษาภายนอกที่คนในพื้นที่แนะนำมา นำแฟ้มสเปกพื้นยางชนิดหนึ่งมาให้ พร้อมราคากลางที่ \"คำนวณไว้แล้ว\" และบอกว่า \"โรงเรียนอื่นใช้ชุดนี้กันหมด\" ครูต้นกล้าดีใจที่ไม่ต้องเขียนเอง ส่วนครูพลศึกษาอยากได้พื้นแบบอื่นที่เหมาะกับกีฬาหลายประเภท"
  ],
  "realCase": "คดีจัดซื้อสนามฟุตซอลของ 12 โรงเรียนในจังหวัดหนึ่งทางภาคอีสาน (งบปี 2555 วงเงิน 45 ล้านบาท) มีการล็อกสเปกพื้นยางจนราคาสูงกว่าตลาดราว 24 ล้านบาท ผู้เสนอราคาฮั้วกัน และที่ปรึกษาแจกแผ่นซีดีราคาให้นำไปใช้ใน TOR องค์คณะอุทธรณ์ในศาลฎีกาพิพากษาเมื่อ 25 สิงหาคม 2569 จำคุกอดีตนักการเมืองและอดีตผู้อำนวยการเขตพื้นที่ (<a href=\"https://matichon.co.th/politics/news_5863453\" target=\"_blank\" rel=\"noopener\">มติชน</a>)",
  "ambiguity": "",
  "commandNote": "ครูต้นกล้า (R2 ถ้าผ่านด่าน 6 มาด้วยการสอนงาน) ต้องการ \"สอนงาน\" ไม่ใช่ \"มอบหมาย\"",
